-- United Tribes, Phase 3: the Academy course content.
--
-- Six modules written for the pastorate to review. Every insert is idempotent
-- ("do nothing" on conflict), so editing a module in the database is never
-- undone by running this file again. Module 1 leaves the church's official
-- vision and mission wording to the pastorate; edit its last section to add it.
--
-- The answer positions below were shuffled once, with a fixed seed, so the
-- right answer is not always the second one.

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  1, $q$the-why$q$, $q$The why$q$, $q$Explain what United Tribes is for, and the three values every circle is built on.$q$, $q$45 min online$q$, 45,
  $q$[{"title": "Why United Tribes exists", "body": ["A church of thousands can feel small in one way: you can sit near someone for years and never learn their name. United Tribes exists so that nobody has to walk a season alone.", "Every member is placed in a circle of up to 12 people who share a season of life and a goal. The circle meets weekly for 12 weeks. At the end we ask one question: did people get where they set out to go?"], "points": ["A circle is up to 12 people, matched by life stage, tribe and Season Goal.", "A season is 12 weeks, with one meeting a week of about 75 minutes.", "A circle is judged by what changed in people’s lives, not by how pleasant the meetings felt."]}, {"title": "Loving God, Loving Others, Loving Life", "body": ["Everything in United Tribes grows from three values. They are the three lines of every circle’s Success Picture, so your circle will write down what each one looks like in practice."], "points": ["Loving God: the faith habit the circle keeps together.", "Loving Others: how the circle carries each other.", "Loving Life: the goal outcome, made specific."]}, {"title": "Where you fit", "body": ["You are not the teacher, the pastor or the counsellor. You are the host who knows the goal, because you have lived it or are living it now, and who makes sure every person is seen.", "You will have an assistant leader and a coach. You hand the meeting to your assistant when you are tired, and you call your coach when something is beyond you."], "points": ["Show up on time, prepared, every week.", "Ask more than you tell.", "Notice who is missing, and reach out.", "Passing on what is beyond your depth is wisdom, not failure."]}, {"title": "In the church’s own words", "body": ["The church’s vision and mission belong to the pastorate. In your first workshop your coach will read the current statements with you and show where each one appears in the life of a circle.", "Until then, hold on to this: United Tribes is how the centre connects people by season of life and calling. Nobody is asked to attend two weekly groups."]}]$q$::jsonb, $q$Write one sentence on why a circle matters to you personally. Keep it. You will share it at your first workshop.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$the-why$q$, 1, $q$How long is a season in United Tribes?$q$, $q$["One year", "12 weeks", "6 weeks", "6 months"]$q$::jsonb, 1, $q$A season is 12 weeks, with one meeting each week.$q$),
  ($q$the-why$q$, 2, $q$What are circles matched by?$q$, $q$["Season of life, tribe and a shared Season Goal", "The leader’s circle of friends", "Whoever signs up first", "Home address alone"]$q$::jsonb, 0, $q$Circles are matched by season of life, tribe and a shared Season Goal.$q$),
  ($q$the-why$q$, 3, $q$Which of these is not one of the three lines of a Success Picture?$q$, $q$["Loving Life", "Loving Success", "Loving God", "Loving Others"]$q$::jsonb, 1, $q$The three lines are Loving God, Loving Others and Loving Life.$q$),
  ($q$the-why$q$, 4, $q$What is a circle judged by?$q$, $q$["How well the leader teaches", "How many people came in week one", "What changed in people’s lives against its Success Picture", "How warm the meetings felt"]$q$::jsonb, 2, $q$A circle is judged by what changed, measured against the Success Picture it agreed.$q$),
  ($q$the-why$q$, 5, $q$What is a leader’s role?$q$, $q$["Teach the whole curriculum alone", "Counsel members through their deepest problems", "Host the circle, ask good questions and notice who is missing", "Keep every secret from the pastorate, whatever happens"]$q$::jsonb, 2, $q$A leader hosts, asks, and notices. What is beyond you goes to your coach or the Care Lead.$q$),
  ($q$the-why$q$, 6, $q$What is the largest a circle can be?$q$, $q$["20", "8", "12", "10"]$q$::jsonb, 2, $q$A circle has up to 12 people.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  2, $q$the-success-picture$q$, $q$The Success Picture$q$, $q$Draft a Season Goal and Success Picture, and coach members to set weekly “When…, I will…” steps.$q$, $q$60 min online$q$, 60,
  $q$[{"title": "One goal in 12 weeks", "body": ["Each circle is built around one Season Goal from the catalogue for its tribe, such as “Step into a leadership role” or “Build a faith-filled home rhythm”. You declared yours when you applied. It is the reason the circle exists and the reason members choose you.", "A goal gives a circle somewhere to go. Without one, a group becomes pleasant but loose."]}, {"title": "Three lines", "body": ["The Success Picture describes what your circle will look like at week 12, with one line for each value. Here is an example for the goal “Step into a leadership role”. Yours will be different."], "points": ["Loving God: Read the week’s passage and say the confession five days a week.", "Loving Others: Pray for our triad weekly; nobody misses twice without a call.", "Loving Life: Each of us completes 10 of 12 weekly steps and has one leadership conversation with a manager."]}, {"title": "Make it specific", "body": ["A line that cannot be checked is a wish. Use numbers, dates and things people can see happen.", "Compare “Grow in confidence” with “Each of us leads one team meeting and asks for feedback by week 10”. Only the second can be seen to happen."], "points": ["Say who does what, and how many times.", "Keep each line under about 25 words.", "If the whole circle cannot tell whether it happened, rewrite it."]}, {"title": "The weekly step: When…, I will…", "body": ["Each member sets one small step at every meeting, written as “When [a moment in my week], I will [one action]”. Tying an action to a moment people already live through makes it far more likely to happen.", "Keep it small enough to do on a bad day. On Friday each member taps one answer: done, partly, or not yet. Not yet carries no shame. It is information for the circle."], "points": ["Good: “When I park at the office on Monday, I will write down the one decision my team needs from me.”", "Weak: “Be more intentional about leadership.”"]}, {"title": "Agree it together", "body": ["You draft the Success Picture on your Circle Card. In week 1 the circle refines it and signs it as its Circle Covenant. Members also read it before they choose your circle, so what you write is a promise."]}]$q$::jsonb, $q$Draft your three lines now. Then ask someone who does not know your goal whether they could tell, at week 12, if each line had happened.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$the-success-picture$q$, 1, $q$Which Success Picture line describes the goal outcome, made specific?$q$, $q$["Loving God", "Loving Life", "Loving Others", "All three equally"]$q$::jsonb, 1, $q$Loving Life is the goal outcome, made specific.$q$),
  ($q$the-success-picture$q$, 2, $q$Which is the best weekly step?$q$, $q$["Try harder this week", "Be more intentional about leadership", "When I park at the office on Monday, I will write down the one decision my team needs from me", "Pray more"]$q$::jsonb, 2, $q$A good step names a moment and one small action: “When…, I will…”.$q$),
  ($q$the-success-picture$q$, 3, $q$Who writes the first draft of a circle’s Success Picture?$q$, $q$["The pastor", "The leader, on the Circle Card", "The platform", "Each member alone"]$q$::jsonb, 1, $q$The leader drafts it on the Circle Card.$q$),
  ($q$the-success-picture$q$, 4, $q$What happens to the Success Picture in week 1?$q$, $q$["It is thrown away", "It is sent to the pastor to rewrite", "Only the coach sees it", "The circle refines it and signs it as its Circle Covenant"]$q$::jsonb, 3, $q$In week 1 the circle refines the picture and signs it as its Circle Covenant.$q$),
  ($q$the-success-picture$q$, 5, $q$On Friday, a member’s step check-in has which three answers?$q$, $q$["Yes, no, maybe", "Great, fine, bad", "Passed, failed, skipped", "Done, partly, not yet"]$q$::jsonb, 3, $q$The answers are done, partly, or not yet.$q$),
  ($q$the-success-picture$q$, 6, $q$Which Loving Life line is the most specific?$q$, $q$["We will pray about our work", "Each of us completes 10 of 12 weekly steps and has one leadership conversation with a manager", "Everyone feels better about their career", "We will grow as leaders"]$q$::jsonb, 1, $q$A specific line says who does what and how many times, so the circle can tell whether it happened.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  3, $q$hosting-the-meeting$q$, $q$Hosting the 75 minutes$q$, $q$Run the meeting flow, ask open questions, use breakout triads and keep time.$q$, $q$60 min online, then role-play in the first workshop$q$, 60,
  $q$[{"title": "The 75 minutes", "body": ["A circle meets once a week for about 75 minutes. A steady shape lets people relax, because they know what is coming."], "points": ["10 minutes, welcome: one sentence from each person on how they really are.", "15 minutes, Loving God: the week’s passage, the confession, two questions.", "25 minutes, Loving Life: review last week’s steps, the skill-share prompt, set this week’s steps.", "15 minutes, Loving Others: pray for each triad and name anyone to follow up.", "10 minutes, close: read the steps aloud, confirm next week, pray."]}, {"title": "Ask open questions", "body": ["A closed question gets a yes or a no. An open question starts with “what”, “how” or “tell me about”, and gives people room.", "Wait. Count to seven in your head before you fill a silence. Someone is usually about to speak."], "points": ["Instead of “Did you pray this week?” ask “What did you notice when you prayed this week?”", "Instead of “Is that clear?” ask “What would you say to a friend who asked you about this?”", "When someone answers, ask “Say more?” before you respond."]}, {"title": "Breakout triads", "body": ["A triad is a group of three inside the circle. Breakouts let quiet people speak and stop one voice taking over. Online, use breakout rooms. In person, turn your chairs.", "Give each triad one clear question and a time. Ask them to bring back one sentence, not a report."]}, {"title": "Keep time, kindly", "body": ["Starting and ending on time is a form of respect, especially in Lagos, where people have crossed traffic to be there. Ask someone in the circle to be timekeeper. If a conversation matters more than the plan, say so aloud and drop something else rather than running over."], "points": ["Start on time even if two people are late, and send them the recap.", "End on time. Stay on for anyone who needs you.", "Audio only is fine online. Data costs money and networks drop."]}, {"title": "Hand over and rest", "body": ["There will be weeks when you are exhausted. Hand the meeting to your assistant leader and rest. A leader who burns out cannot lead for twelve weeks."]}]$q$::jsonb, $q$Plan your first meeting using the 75-minute shape. In the first workshop you will lead five minutes of it, with feedback from a coach.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$hosting-the-meeting$q$, 1, $q$About how long is one circle meeting?$q$, $q$["75 minutes", "It varies with the topic", "45 minutes", "2 hours"]$q$::jsonb, 0, $q$A circle meets for about 75 minutes.$q$),
  ($q$hosting-the-meeting$q$, 2, $q$Which is an open question?$q$, $q$["Did you pray this week?", "Are you okay?", "What did you notice when you prayed this week?", "Is that clear?"]$q$::jsonb, 2, $q$An open question starts with what, how or tell me about, and cannot be answered with yes or no.$q$),
  ($q$hosting-the-meeting$q$, 3, $q$One member talks for minutes and the others are quiet. What helps most?$q$, $q$["Ignore it and hope it ends", "Skip questions for the evening", "Thank them, then invite others by name, and speak privately after if it continues", "Cut them off in front of everyone"]$q$::jsonb, 2, $q$Thank them, invite others by name, and speak privately afterwards if it continues.$q$),
  ($q$hosting-the-meeting$q$, 4, $q$What is a triad?$q$, $q$["The three lines of the Success Picture", "A group of three people inside the circle who pray and check in on each other", "Three circles meeting together", "A leadership team of three"]$q$::jsonb, 1, $q$A triad is three people inside the circle who pray for and check in on each other.$q$),
  ($q$hosting-the-meeting$q$, 5, $q$You are exhausted and the meeting starts in an hour. What should you do?$q$, $q$["Hand the meeting to your assistant leader and rest", "Run it anyway and say nothing", "Cancel without telling anyone", "Ask the quietest member to lead"]$q$::jsonb, 0, $q$Hand the meeting to your assistant leader and rest. A leader who burns out cannot lead for twelve weeks.$q$),
  ($q$hosting-the-meeting$q$, 6, $q$Two people are late. What do you do?$q$, $q$["Wait as long as it takes for everyone", "Restart from the beginning", "Start on time and send them the recap", "Mark them absent without contacting them"]$q$::jsonb, 2, $q$Start on time, and send the recap to anyone who missed it.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  4, $q$knowing-your-people$q$, $q$Knowing your people$q$, $q$Draw out quiet members, steer dominant voices, and keep what people share private.$q$, $q$45 min online$q$, 45,
  $q$[{"title": "People join in differently", "body": ["When members signed up they answered six quick this-or-that questions: a lively group chat or a quiet one-to-one, a clear plan or see where it goes, something new or what works, say what I think or keep the peace, open up quickly or once I trust people, talk it through or learn by doing.", "These answers help place people in a balanced circle. They are a matching aid, not a personality test. You will not see anyone’s individual answers, and neither will other members. What you will notice in the room is the same thing, and that is what you work with."]}, {"title": "Draw out the quiet", "body": ["Quiet does not mean uninterested. Some people think before they speak. Some need to trust the room first. Invite, do not ambush."], "points": ["Give the question a minute before you take answers.", "Use triads first, so a quiet person has already said it once.", "Ask by name, with an easy way out: “Ngozi, would you like to add anything, or pass?”", "Follow up in private: “I valued what you said last week.”"]}, {"title": "Steer the dominant voice", "body": ["The person who talks most usually cares most. Do not shame them. Redirect their energy."], "points": ["Thank them, then invite others by name.", "Give them a job: timekeeper, welcomer or note-taker.", "If it continues, speak privately after the meeting, kindly and plainly.", "Tell your coach if it does not change."]}, {"title": "Respect age and seniority", "body": ["In Nigeria, age and position shape how freely people speak. In a circle of people in the same season of life this eases, but not completely. Ask each person what they like to be called, and use it. Make it normal to disagree gently, and show that you can be corrected yourself."]}, {"title": "Celebrate", "body": ["Celebration is how love is shown. Birthdays, new babies, promotions, a business registered, an answered prayer: make room for them. A minute of real celebration does more than a week of advice.", "Celebrate only what people have chosen to share. A member’s birthday reaches you only if they chose to give it, and the year is never asked."]}]$q$::jsonb, $q$Think of the loudest and the quietest person you know. Write one thing you would do for each if they were in your circle.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$knowing-your-people$q$, 1, $q$How should you invite a quiet member to speak?$q$, $q$["Call on them suddenly in front of everyone", "Ask the whole circle to look at them", "Never ask them anything", "Give a moment to think, use triads first, and invite by name with an easy way to pass"]$q$::jsonb, 3, $q$Invite, do not ambush: give time, use triads, and ask by name with an easy way to pass.$q$),
  ($q$knowing-your-people$q$, 2, $q$One member dominates the conversation. What is a good first step?$q$, $q$["Say nothing and let the others adjust", "Thank them, invite others by name, or give them a useful job", "Interrupt them every time", "Remove them from the circle"]$q$::jsonb, 1, $q$Thank them and redirect their energy. Speak privately if it continues.$q$),
  ($q$knowing-your-people$q$, 3, $q$Will you see members’ answers to the six this-or-that questions?$q$, $q$["No. They help place people and stay private", "Only on birthdays", "Yes, all of them", "Only for the loudest members"]$q$::jsonb, 0, $q$Those answers help balance circles. Individual answers are never shown to leaders or members.$q$),
  ($q$knowing-your-people$q$, 4, $q$How should you address a member?$q$, $q$["By surname only", "By title only", "By whatever name you prefer", "By the name they like to be called"]$q$::jsonb, 3, $q$Ask each person what they like to be called, and use it.$q$),
  ($q$knowing-your-people$q$, 5, $q$Why does celebration matter in a circle?$q$, $q$["It is how love is shown, and it builds friendship", "It makes meetings longer", "It replaces prayer", "The platform requires it"]$q$::jsonb, 0, $q$Celebration is how love is shown, and shared good news builds friendship.$q$),
  ($q$knowing-your-people$q$, 6, $q$What is true of quiet members?$q$, $q$["They prefer not to be greeted", "They should be asked to leave", "They need a gentler way in, and often have a lot to say", "They do not care"]$q$::jsonb, 2, $q$Quiet is not the same as uninterested. Give a gentler way in.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  5, $q$care-and-safeguarding$q$, $q$Care and safeguarding$q$, $q$Use the care ladder, escalate urgent risk the same day, and protect member information.$q$, $q$60 min online, then a signed declaration$q$, 60,
  $q$[{"title": "The care ladder", "body": ["When someone tells you something heavy, you do not have to solve it. You have to know which rung it is on and who takes it next."], "points": ["Practical: a need you can help meet, such as a job lead, a lift or food. Tell your assistant leader or coach. The platform tracks it with a seven-day deadline.", "Pastoral: grief, a marriage under strain, doubt or conflict. Tell your coach, and a pastoral team member follows up. Stay present, but do not counsel beyond your training.", "Urgent: anyone who may harm themselves or someone else, or who is being harmed. Contact the Care Lead the same day. If anyone is in immediate danger, call 112, Nigeria’s emergency number."]}, {"title": "When someone may be at risk", "body": ["Stay with them. Take it seriously. Do not promise to keep it secret. You can say: “I care about you, and this is too big for me to carry alone. I need to bring in someone trained to help.”"], "points": ["Never promise secrecy.", "Do not investigate or confront anyone.", "Contact the Care Lead the same day. Do not wait for the next meeting.", "Write down only what you saw and heard, not your opinion.", "Look after yourself afterwards. Tell your coach how it affected you."]}, {"title": "Children and young people", "body": ["Circles are for adults. If a child or young person is ever mentioned as being at risk, treat it as urgent and contact the Care Lead the same day. Never be alone with a child connected to your circle, in person or online. Meet in the open or with another adult present."]}, {"title": "Requests for money", "body": ["Members will sometimes ask a leader for a loan. Decline kindly and keep the friendship. Route the need through the care ladder as a practical need, so that help comes from the church rather than from one person’s pocket."], "points": ["You can say: “I can’t lend money as your leader, but I will make sure the right people hear about this.”", "Tell your coach in the same week.", "Do not accept gifts of money."]}, {"title": "Keeping information private", "body": ["What is shared in the circle stays in the circle, except where someone is at risk. Under the Nigeria Data Protection Act 2023, personal information must be handled with care, kept only as long as it is needed, and shared only with people who need it."], "points": ["Do not forward screenshots, voice notes or circle chats.", "Keep prayer requests in the circle’s private prayer list on the platform, not in a WhatsApp group that others can join.", "Do not store members’ details in your own notes.", "If you lose a device that has circle details on it, tell your coach at once."]}, {"title": "The declaration", "body": ["After you pass the quiz you will be asked to sign a short safeguarding declaration. It promises what you have just learned. Read it slowly."]}]$q$::jsonb, $q$Ask your coach for the Care Lead’s contact and save it in your phone today, before you need it.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$care-and-safeguarding$q$, 1, $q$A member says something suggesting they may harm themselves. What do you do?$q$, $q$["Tell the circle so they can pray", "Promise to keep it secret and pray with them", "Wait to see if they mention it again", "Stay with them, take it seriously and contact the Care Lead the same day"]$q$::jsonb, 3, $q$Stay with them, take it seriously, and contact the Care Lead the same day. Never promise secrecy.$q$),
  ($q$care-and-safeguarding$q$, 2, $q$Which of these is on the practical rung of the care ladder?$q$, $q$["A person who may be in danger", "A marriage in crisis", "A member who needs a lift and food this week", "A doctrinal argument"]$q$::jsonb, 2, $q$A need you can help meet, like a lift or food, is practical. Danger is urgent, and a marriage in crisis is pastoral.$q$),
  ($q$care-and-safeguarding$q$, 3, $q$A member asks you for a personal loan. What is the best response?$q$, $q$["Ignore the request", "Ask the circle to contribute", "Lend what you can", "Decline kindly and route the need through the care ladder"]$q$::jsonb, 3, $q$Decline kindly, and send the need through the care ladder so help comes from the church.$q$),
  ($q$care-and-safeguarding$q$, 4, $q$Can you promise a member that you will keep everything they say secret?$q$, $q$["Yes, always", "Only for prayer requests", "Never. Confidentiality has an exception when someone is at risk", "Yes, if they ask nicely"]$q$::jsonb, 2, $q$Never promise secrecy. What is shared stays in the circle, except where someone is at risk.$q$),
  ($q$care-and-safeguarding$q$, 5, $q$Where should a circle’s prayer requests be kept?$q$, $q$["In the circle’s private prayer list on the platform", "On a church noticeboard", "In a public WhatsApp group", "In your own notes app"]$q$::jsonb, 0, $q$Keep them in the circle’s private prayer list on the platform.$q$),
  ($q$care-and-safeguarding$q$, 6, $q$Someone is in immediate danger. Which number can you call in Nigeria?$q$, $q$["911", "1000", "999", "112"]$q$::jsonb, 3, $q$112 is Nigeria’s emergency number. Then contact the Care Lead the same day.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;

insert into public.academy_modules (number, slug, title, outcome, format, minutes, lesson, practice) values (
  6, $q$using-the-platform$q$, $q$Using the platform$q$, $q$Submit the weekly log, read your circle’s dashboard, and approve testimonies.$q$, $q$30 min online$q$, 30,
  $q$[{"title": "Your Monday prep pack", "body": ["Every Monday of the season you receive the week’s meeting guide, questions tied to Sunday’s message, your circle’s prayer list, and a list of who needs a follow-up."]}, {"title": "The two-minute log", "body": ["Straight after each meeting you get a link to the log. It takes about two minutes and replaces any report."], "points": ["Attendance: tap present, apologised or absent for each member.", "Meeting energy, from 1 to 5.", "One highlight, in a sentence.", "Prayer requests, which feed the circle’s private prayer list.", "Testimonies, only with the member’s consent.", "A care flag: none, practical, pastoral or urgent.", "Whether you need help from your coach this week."]}, {"title": "What the platform does for you", "body": ["When a member misses a meeting, the platform suggests a warm message for you to send. After two in a row it asks you to call, and the member gets a short note to say they were missed. After three it creates a task for your coach.", "If you forget the log, you are reminded after 24 hours and your coach is told after 48 hours. That is not a penalty. It is how help keeps reaching you."]}, {"title": "Testimonies", "body": ["When a member shares a testimony and agrees to it being shared, it comes to you to approve before anyone else sees it. Approved testimonies are tagged by tribe and goal and may be shared at Harvest Night.", "Do not approve a testimony that names someone who has not agreed, or that reveals another person’s private matter."]}, {"title": "Your circle’s dashboard", "body": ["The dashboard shows attendance, steps completed, how members feel they belong, open follow-ups and testimonies. Use it to see who needs a call. It is not a score of you."]}]$q$::jsonb, $q$Open the platform on your phone and add it to your home screen, so the weekly log is one tap away.$q$)
on conflict (slug) do nothing;

insert into public.academy_questions (module_id, position, prompt, options, correct, explanation)
select m.id, v.position, v.prompt, v.options, v.correct, v.explanation
from (values
  ($q$using-the-platform$q$, 1, $q$How long should the weekly log take?$q$, $q$["It depends on the circle", "An hour", "Twenty minutes", "About two minutes"]$q$::jsonb, 3, $q$The log is designed to take about two minutes.$q$),
  ($q$using-the-platform$q$, 2, $q$When can others see a testimony?$q$, $q$["Never", "As soon as the member types it", "Only at Harvest Night", "After you approve it, with the member’s consent"]$q$::jsonb, 3, $q$A testimony is shared only with the member’s consent and after the leader approves it.$q$),
  ($q$using-the-platform$q$, 3, $q$A member misses three meetings in a row. What does the platform do?$q$, $q$["Tells the whole circle", "Nothing", "Removes them from the circle", "Creates a task for your coach"]$q$::jsonb, 3, $q$After three missed meetings a task is created for the coach.$q$),
  ($q$using-the-platform$q$, 4, $q$Where do prayer requests from the log go?$q$, $q$["The circle’s private prayer list", "The church website", "They are deleted", "A public channel"]$q$::jsonb, 0, $q$They feed the circle’s private prayer list.$q$),
  ($q$using-the-platform$q$, 5, $q$When does the prep pack arrive?$q$, $q$["Every Monday of the season", "Every day", "Only in week one", "The Saturday before the season"]$q$::jsonb, 0, $q$The prep pack arrives every Monday of the season.$q$)
) as v (slug, position, prompt, options, correct, explanation)
join public.academy_modules m on m.slug = v.slug
on conflict (module_id, position) do nothing;
